-- Austria: 2014 / B2G mandate in force
DELETE FROM deep_dive_stat_translations WHERE stat_id IN (
  SELECT ds.id FROM deep_dive_stats ds
    JOIN countries c ON c.id = ds.country_id
    JOIN deep_dive_stat_translations t ON t.stat_id = ds.id AND t.lang = 'en'
   WHERE c.name_en = 'Austria' AND t.stat_label = 'B2G mandate in force');
DELETE FROM deep_dive_stats WHERE id IN (
  SELECT ds.id FROM deep_dive_stats ds
    JOIN countries c ON c.id = ds.country_id
    LEFT JOIN deep_dive_stat_translations t ON t.stat_id = ds.id
   WHERE c.name_en = 'Austria' AND t.stat_id IS NULL);

